//! 关闭 WebView 自带的浏览器外壳行为。
//!
//! Tauri 的窗口内核其实是一个浏览器, 默认带着整套浏览器外壳行为: 右键原生菜单、F5 / Ctrl+R
//! 刷新、Ctrl+P 打印、Ctrl+F 查找、F12 开发者工具…… 这些行为出现在桌面应用里既突兀, 又会破坏
//! 编辑器状态 —— 例如误按 F5 会直接刷新页面, 丢掉未保存的改动。
//!
//! 策略只有一份 ([`flags`]), 各平台用各自能做到的方式执行同一份策略:
//! * 所有平台: 注入脚本在页面里 preventDefault 掉这些默认行为;
//! * Windows: WebView2 的加速键在页面之下处理, 脚本拦不住, 于是再用 WebView2 设置在浏览器层
//!   关同样的规则 (顺便关掉开发者工具本身)。
//!
//! 唯一的例外是开发者工具: 发布构建连 F12 一起禁掉, 调试构建保留, 但要由前端监听 F12 调用
//! [`open_devtools`] 唤起 —— 加速键关了之后 WebView2 不会自己响应 F12。
//!
//! 往窗口里拖文件也属于浏览器行为, 但它归前端管 (快捷键列表里没有拖放事件): 页面里由
//! `src/main.tsx` 在 `window` 上兜底。Windows 上 wry 还会先用自己的拖放目标把整个 drop 吃掉
//! (`dragDropEnabled` 默认为 true), 所以页面根本收不到拖入的文件。

use tauri_plugin_prevent_default::{Builder, Flags};

/// 要禁用的浏览器行为, 所有平台共用这一份。
///
/// 只放过 Shift+Tab —— 它同时是应用内的键盘导航键, 拦掉就没法用键盘在控件之间移动了。
fn flags() -> Flags {
    Flags::all().difference(Flags::FOCUS_MOVE)
}

/// 构建拦截浏览器默认行为的插件。
pub fn plugin<R: tauri::Runtime>() -> tauri::plugin::TauriPlugin<R> {
    let builder = Builder::new().with_flags(flags());

    // 发布构建: F12 也一并禁掉 (调试构建留给开发者工具)
    #[cfg(not(debug_assertions))]
    let builder = builder.shortcut(tauri_plugin_prevent_default::KeyboardShortcut::new("F12"));

    // Windows: 同一份策略在浏览器层再执行一次
    #[cfg(target_os = "windows")]
    let builder = builder.platform(
        tauri_plugin_prevent_default::PlatformOptions::new()
            .browser_accelerator_keys(false)
            .default_context_menus(false)
            .dev_tools(cfg!(debug_assertions)),
    );

    builder.build()
}

/// 打开当前窗口的开发者工具 (只有调试构建会真的打开)。
///
/// 浏览器快捷键关闭后 WebView2 不再响应 F12, 因此调试构建下由前端监听 F12 调用本命令;
/// 发布构建里开发者工具已被 [`plugin`] 关闭, 这个命令不做任何事。
#[tauri::command]
pub fn open_devtools(window: tauri::WebviewWindow) {
    #[cfg(debug_assertions)]
    window.open_devtools();
    #[cfg(not(debug_assertions))]
    let _ = window;
}
